import"./hoisted.Dgxu4n85.js";const c="https://kreatu-api.vercel.app/api/create_preference";document.querySelectorAll(".btn-plan").forEach(t=>{t.addEventListener("click",async()=>{const e=t.dataset.plan,a=parseFloat(t.dataset.price),o=document.getElementById("pay-loading");o.style.display="flex";try{const s=await(await fetch(c,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({title:`Plan ${e} - KreatuSitioWeb`,price:a,quantity:1})})).json();if(s.init_point)window.location.href=s.init_point;else throw new Error("No se recibio URL de pago")}catch(r){o.style.display="none",alert("Error al procesar el pago. Por favor intenta de nuevo."),console.error(r)}})});const n=document.getElementById("contact-form"),i=document.getElementById("success-msg");n?.addEventListener("submit",async t=>{t.preventDefault();const e=n.querySelector('button[type="submit"]');e.disabled=!0,e.textContent="Enviando…";try{(await fetch(n.action,{method:"POST",body:new FormData(n),headers:{Accept:"application/json"}})).ok?(n.style.display="none",i&&i.classList.add("visible")):(e.disabled=!1,e.textContent="Enviar mensaje →",alert("Hubo un error al enviar. Por favor intenta de nuevo."))}catch{e.disabled=!1,e.textContent="Enviar mensaje →",alert("Sin conexión. Por favor intenta de nuevo.")}});
